import gzip,collections
# Print all reads containing the scaffold that contribute to a few discrepant counts.
checks=[('LIB6','VAL2_0001'),('LIB6','VAL2_0003'),('LIB6','VAL2_0005')]
lib={}
for line in open('/task/input/library.tsv'):
    f=line.rstrip().split('\t')
    if f[0]!='sgRNA': lib[f[0]]=f[1]
for sample,sg in checks:
    wanted=lib[sg]
    found=[]
    with gzip.open('/task/input/fastq/'+sample+'.fastq.gz','rt') as fh:
        for n,line in enumerate(fh):
            if n%4!=1: continue
            s=line.rstrip(); rc=s.translate(str.maketrans('ACGTN','TGCAN'))[::-1]
            hits=[]
            for label,r in [('fwd',s),('rc',rc)]:
                start=0
                while True:
                    p=r.find('GTTTTAGAGCT',start)
                    if p<0: break
                    if p>=20 and r[p-20:p]==wanted: hits.append((label,p))
                    start=p+1
            if hits: found.append((n//4,hits,s))
    print(sample,sg,'reads matching spacer before any scaffold:',len(found))
    for rec in found[:5]: print(' ',rec)
